import{_ as a,o as r,c as e,a3 as d}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"为什么选择曦寒","description":"","frontmatter":{},"headers":[],"relativePath":"why.md","filePath":"why.md","lastUpdated":1786258579000}'),o={name:"why.md"};function n(l,t,i,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="为什么选择曦寒" tabindex="-1">为什么选择曦寒 <a class="header-anchor" href="#为什么选择曦寒" aria-label="Permalink to &quot;为什么选择曦寒&quot;">​</a></h1><p>完整能力清单在 <a href="./features">功能清单</a>，这一页不重复。它只回答三个问题：</p><ol><li>它究竟替我省掉什么？</li><li>我这个项目适合拿它当起点吗？</li><li>它和别的中后台方案有什么不同？</li></ol><p>中后台的选型成本主要不在「能不能跑起来」，而在<strong>三年后还改不改得动</strong>。所以这一页会把代价和亮点写在一起。</p><h2 id="_30-秒结论" tabindex="-1">30 秒结论 <a class="header-anchor" href="#_30-秒结论" aria-label="Permalink to &quot;30 秒结论&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">适合这样的项目</p><ul><li><strong>企业内部系统 / 行业业务系统 / B 端 SaaS</strong>：用户有组织归属，权限要按人按数据切</li><li><strong>需要多租户</strong>：一套代码服务多个客户，且要能按版本卖不同的功能包</li><li><strong>有合规与审计要求</strong>：谁在什么时候改了哪条数据、动了谁的权限，都要留痕可查</li><li><strong>.NET 后端 + Vue 前端</strong>的团队，希望前后端两侧都有现成规范可循</li></ul></div><div class="warning custom-block"><p class="custom-block-title">这些情况建议先别选</p><ul><li><strong>面向 C 端的门户 / 交易 / 高并发系统</strong>：它是中后台内核，设计目标不是极限吞吐</li><li><strong>被锁在 .NET 6 / 8</strong>，或团队已深度绑定 EF Core：底座是 .NET 10 + SqlSugar</li><li><strong>前端团队是 React 技术栈</strong>：前端是 Vue 3，迁移等于重写</li><li><strong>只需要一个「有登录和菜单」的小后台</strong>：权限、租户、审计这套模型对小系统是过度设计</li></ul></div><h2 id="一、它替你省掉的那几个月" tabindex="-1">一、它替你省掉的那几个月 <a class="header-anchor" href="#一、它替你省掉的那几个月" aria-label="Permalink to &quot;一、它替你省掉的那几个月&quot;">​</a></h2><p>每个中后台项目开工时都要重做一遍下面这些东西。它们不产生业务价值，但每一样做不好都会在半年后变成事故：</p><table tabindex="0"><thead><tr><th>你本来要写</th><th>它已经内置</th></tr></thead><tbody><tr><td>登录、令牌刷新、多端会话、找回密码</td><td><a href="./backend/authentication">JWT 双令牌</a>、账号密码 / 邮箱短信验证码 / OAuth2 / 2FA、会话管理</td></tr><tr><td>角色菜单权限，然后被业务追问「他只能看自己部门的」</td><td><a href="./backend/permission">RBAC + ABAC</a> + 数据范围 + 字段级脱敏，四个正交维度</td></tr><tr><td>组织架构，然后发现部门树的上下级查询很慢</td><td><a href="./backend/organization">部门闭包表</a> + 岗位 + 用户多部门归属</td></tr><tr><td>多租户，然后在每个查询里手动加 <code>where tenant_id =</code></td><td><a href="./backend/multi-tenancy">字段级隔离</a>内建于数据层，写路径有越权写守卫</td></tr><tr><td>操作日志，然后发现密码和令牌被明文记进了库</td><td><a href="./backend/logging">七类审计日志</a>，落库前自动脱敏</td></tr><tr><td>增删改查页面，一张表写一遍</td><td><a href="./backend/code-generation">代码生成</a>：实体 → DTO → API → 前端页一键产出</td></tr><tr><td>站内信、邮件、短信、群机器人各写一套</td><td><a href="./backend/messaging">消息中心</a> 四渠道扇出 + 模板渲染 + SignalR 实时推送</td></tr></tbody></table><p>内置 <strong>88 张表</strong>的数据模型与 <strong>50 多个后台页面</strong>，是这些能力落地后的实际体量。</p><h2 id="二、五个真正拉开差距的地方" tabindex="-1">二、五个真正拉开差距的地方 <a class="header-anchor" href="#二、五个真正拉开差距的地方" aria-label="Permalink to &quot;二、五个真正拉开差距的地方&quot;">​</a></h2><p>「有这个功能」和「这个功能经得起用」是两件事。下面五点是它与常见后台模板的实质差异。</p><h3 id="_1-权限不止「角色—菜单」两层" tabindex="-1">1. 权限不止「角色—菜单」两层 <a class="header-anchor" href="#_1-权限不止「角色—菜单」两层" aria-label="Permalink to &quot;1. 权限不止「角色—菜单」两层&quot;">​</a></h3><p>大多数后台模板的权限模型到「角色绑菜单、菜单绑按钮」为止。业务提出「区域经理只能看本区域、且只能在工作时间审批、且金额超过 50 万要转审批」时，就得改代码。</p><p>曦寒把权限拆成<strong>四个正交维度</strong>，再加两套治理机制：</p><table tabindex="0"><thead><tr><th>维度</th><th>回答的问题</th></tr></thead><tbody><tr><td>权限码 <code>module:resource:action</code></td><td>你能不能做这个操作</td></tr><tr><td>数据范围（本人 / 部门 / 租户）</td><td>这个操作能作用到哪些数据</td></tr><tr><td>ABAC 属性条件</td><td>在什么时间、什么 IP、什么资源状态下才成立</td></tr><tr><td>字段级脱敏</td><td>同一条数据里，哪些列你看得见明文</td></tr></tbody></table><ul><li><strong>约束规则引擎</strong>：静态 / 动态职责分离、互斥、基数、先决条件、时间、位置等八类规则，违规可拒绝 / 警告 / 仅记录 / 转审批</li><li><strong>权限委托</strong>：委托人 → 被委托人 → 权限范围 → 生效与到期时间窗，可随时撤销，全程留痕</li></ul><blockquote><p>完整模型见 <a href="./backend/permission">权限模型</a> 与 <a href="./backend/approval">审批与约束</a>。</p></blockquote><h3 id="_2-多租户是内建维度-不是补丁" tabindex="-1">2. 多租户是内建维度，不是补丁 <a class="header-anchor" href="#_2-多租户是内建维度-不是补丁" aria-label="Permalink to &quot;2. 多租户是内建维度，不是补丁&quot;">​</a></h3><p>多租户如果做成「在业务代码里记得加过滤条件」，那么漏一处就是数据泄露。这里它落在数据层：租户过滤由框架统一施加，全局数据用 <code>TenantId=0</code> 约定，写路径另有守卫防止租户态误改全局行。</p><p>配套的还有商业化需要的那部分：租户版本（Edition）以权限白名单在运行时门控功能，开通时一站式建管理员与授权，降级自动回收越权授权。超级管理员可在平台态切入任意租户代为运维。</p><blockquote><p>见 <a href="./backend/multi-tenancy">多租户与版本</a>。</p></blockquote><h3 id="_3-菜单、路由、权限码只有一份真源" tabindex="-1">3. 菜单、路由、权限码只有一份真源 <a class="header-anchor" href="#_3-菜单、路由、权限码只有一份真源" aria-label="Permalink to &quot;3. 菜单、路由、权限码只有一份真源&quot;">​</a></h3><p>后台系统最常见的腐化点，是菜单在数据库里、路由在前端代码里、权限码在第三个地方，三份逐渐对不上。</p><p>这里后端的 <code>PageRegistry</code> 统一登记页面码、路由路径、前端组件路径、权限码与国际化键，菜单种子据此同步；前端按后端下发的结果生成路由。<strong>新增一个页面只在一处登记</strong>，前端不再维护第二份清单。</p><blockquote><p>见 <a href="./frontend/routing">菜单与路由</a>。</p></blockquote><h3 id="_4-列表页由配置生成-且三重感知" tabindex="-1">4. 列表页由配置生成，且三重感知 <a class="header-anchor" href="#_4-列表页由配置生成-且三重感知" aria-label="Permalink to &quot;4. 列表页由配置生成，且三重感知&quot;">​</a></h3><p>中后台八成的页面是「搜索 + 表格 + 导出」。这里它们由 Schema 配置生成，内置列设置、密度切换、高级搜索（时间区间、枚举多选）、个人视图保存、树形模式与列宽拖拽。</p><p>关键在于它对三件事有感知：<strong>权限</strong>（页面、字段、操作三级按权限码过滤，字段级脱敏）、<strong>租户</strong>、<strong>个人偏好</strong>（列设置与搜索条件同步到后端，换台电脑还在）。</p><blockquote><p>见 <a href="./frontend/schema-page">Schema 驱动页面</a>。</p></blockquote><h3 id="_5-底座可以单独带走" tabindex="-1">5. 底座可以单独带走 <a class="header-anchor" href="#_5-底座可以单独带走" aria-label="Permalink to &quot;5. 底座可以单独带走&quot;">​</a></h3><p>它的后端建立在 <a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework</a> 之上，而框架是 <strong>66 个可独立引用的 NuGet 包</strong>，本身就是公开发布的产品。</p><p>这意味着两个方向都通：你可以拿整套 BasicApp 起步，也可以只借走框架的某几个模块用在自己的项目里。BasicApp 使用的全部是框架公开的接口，<strong>没有内部特权 API</strong>——所以「先用模板上线，之后逐步换成自己的实现」这条路是通的，不需要换底座。</p><h2 id="三、中后台方案的四条路线" tabindex="-1">三、中后台方案的四条路线 <a class="header-anchor" href="#三、中后台方案的四条路线" aria-label="Permalink to &quot;三、中后台方案的四条路线&quot;">​</a></h2><p>同类方案不在一个平面上，而是四条路线。下面只描述路线特征，不做优劣评判——<strong>很多时候「不选曦寒」才是对的</strong>。</p><table tabindex="0"><thead><tr><th>路线</th><th>代表</th><th>你得到什么</th><th>你付出什么</th><th>什么时候选它</th></tr></thead><tbody><tr><td><strong>A. 从零自建</strong></td><td>ASP.NET Core + Vue + 自选组件</td><td>完全贴合业务，没有多余抽象</td><td>身份、权限、租户、审计要自己写并维护多年</td><td>系统形态特殊，且团队有稳定架构能力</td></tr><tr><td><strong>B. 商业中后台 / 低代码平台</strong></td><td>各类商业 aPaaS 与低代码平台</td><td>有 SLA、有实施支持、非开发者也能配置</td><td>授权费用、平台绑定，深度定制受平台能力边界限制</td><td>需求以配置为主，且预算与合规要求指向商业产品</td></tr><tr><td><strong>C. 开源后台管理模板</strong></td><td>ZR.Admin.NET、YuebonCore 等</td><td>开箱就是一套完整后台，社区素材多</td><td>底座常与模板一体，长大后拆解成本高</td><td>需求接近标准后台，追求最快上线</td></tr><tr><td><strong>D. 框架 + 中后台内核</strong></td><td>Admin.NET（基于 Furion）、ABP 官方启动模板、曦寒基础应用</td><td>既有可投产的成品，又有可独立演进的底座</td><td>需要理解底座的模块化与分层概念，学习曲线更陡</td><td>系统会长期长大，且不希望被模板绑死</td></tr></tbody></table><p><strong>曦寒站在 D。</strong> 与路线 C 最实质的区别是：模板部分可以逐块替换，底座不用换。与路线 B 的区别是：全部代码在你手上，MIT 许可，没有功能墙，代价是没有商业支持。</p><h2 id="四、用最小成本验证" tabindex="-1">四、用最小成本验证 <a class="header-anchor" href="#四、用最小成本验证" aria-label="Permalink to &quot;四、用最小成本验证&quot;">​</a></h2><p>别信任何一页文档的自述，点一遍最快：</p><table tabindex="0"><thead><tr><th>花多久</th><th>做什么</th><th>你会验证到什么</th></tr></thead><tbody><tr><td><strong>10 分钟</strong></td><td>打开 <a href="https://basicapp.xihanfun.com" target="_blank" rel="noreferrer">在线用例</a>，用 <code>superadmin</code> / <code>SuperAdmin@123</code> 登录</td><td>交互质感与能力广度是否够用</td></tr><tr><td><strong>半天</strong></td><td>跟着 <a href="./getting-started">快速开始</a> 在本地跑起前后端</td><td>上手成本，以及你的环境是否顺畅</td></tr><tr><td><strong>一天</strong></td><td>读 <a href="./project-structure">目录结构与代码地图</a> → <a href="./backend/request-lifecycle">请求生命周期</a> → <a href="./backend/development">二次开发</a></td><td>「加一个业务功能要动几个文件」这个真实成本</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">演示环境</p><p>在线用例是公开演示环境，数据会被定期重置，请勿录入任何真实数据。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./getting-started">快速开始</a>：在本地把系统跑起来</li><li><a href="./overview">系统概述</a>：定位、技术栈、按角色的阅读路线</li><li><a href="./features">功能清单</a>：逐领域的完整能力列表</li><li><a href="https://framework.docs.xihanfun.com/why" target="_blank" rel="noreferrer">为什么选择曦寒框架</a>：如果你要的是底座而不是成品</li></ul>',44)])])}const b=a(o,[["render",n]]);export{g as __pageData,b as default};
